function archiveUri(uri) {
  let parsed;
  try {
    parsed = new URL(uri);
  } catch {
    throw new Error("Unsupported APT URI");
  }
  const paths = {
    "azure.archive.ubuntu.com": "ubuntu",
    "archive.ubuntu.com": "ubuntu",
    "security.ubuntu.com": "ubuntu",
